window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a4350d1e948d085d"]={"versions": [{"id": "FIG-a4350d1e948d085d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im Kontext des AUTOSAR Security Extract Templates (<code>AUTOSAR_TPS_SecurityExtractTemplate</code>). Das Modell definiert die Struktur des <code>SecurityEventStateFilter</code>, mit dem das Filtern bzw. Blockieren von Security-Events in Abhängigkeit von aktuellen Systemzuständen sowohl für die Classic Platform (CP) als auch für die Adaptive Platform (AP) konfiguriert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>SecurityEventStateFilter</code>: Spezialisierung von <code>AbstractSecurityEventFilter</code>. Zentrale Filterklasse zur Zustandsfilterung von Security-Events.\n</li><li><code>BlockState</code>: Spezialisierung von <code>Identifiable</code>. Repräsentiert Blockierzustände für die Classic Platform. Referenziert über die Assoziation <code>+blockIfStateActiveCp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>ModeDeclaration</code>: Spezialisierung von <code>AtpStructureElement</code> und <code>Identifiable</code>. Besitzt das Attribut <code>+ value: PositiveInteger [0..1]</code>. Dient der Referenzierung von Zuständen im AP-Kontext mittels Instanzreferenz (<code>«instanceRef»</code>) über die gerichtete Beziehung <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>FunctionGroupStateInFunctionGroupSetInstanceRef</code>: Spezialisierung von <code>AtpInstanceRef</code> (farblich als Instanzreferenz-Container hervorgehoben). Eingebunden per Komposition (ausgefüllte Raute) über die Rolle <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bewertet die Filterlogik eines <code>SecurityEventStateFilter</code> beim Eintreffen eines Sicherheitsereignisses den aktuellen Systemzustand: Befindet sich das System in einem Zustand, der über <code>blockIfStateActiveCp</code> (Classic Platform) oder über <code>blockIfStateActiveAp</code> (Adaptive Platform bzw. Execution Management Function Groups) hinterlegt ist, wird das Event blockiert bzw. nicht weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-M2-Metamodell für Security Extracts. Konfiguratoren und Werkzeugketten müssen bei der Modellierung von <code>SecurityEventStateFilter</code> sicherstellen, dass je nach Zielplattform (CP oder AP) die korrekten Zustandsreferenzen modelliert werden: <code>BlockState</code> für CP-Zustände sowie <code>FunctionGroupStateInFunctionGroupSetInstanceRef</code> bzw. <code>ModeDeclaration</code> für AP-Funktionsgruppenzustände. Alle Rollen besitzen die Kardinalität <code>0..*</code> und sind somit optional sowie mehrfach instanziierbar.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a601aa03f5394eaa", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im Kontext des AUTOSAR Security Extract Templates (<code>AUTOSAR_TPS_SecurityExtractTemplate</code>). Das Modell definiert die Struktur des <code>SecurityEventStateFilter</code>, mit dem das Filtern bzw. Blockieren von Security-Events in Abhängigkeit von aktuellen Systemzuständen sowohl für die Classic Platform (CP) als auch für die Adaptive Platform (AP) konfiguriert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>SecurityEventStateFilter</code>: Spezialisierung von <code>AbstractSecurityEventFilter</code>. Zentrale Filterklasse zur Zustandsfilterung von Security-Events.\n</li><li><code>BlockState</code>: Spezialisierung von <code>Identifiable</code>. Repräsentiert Blockierzustände für die Classic Platform. Referenziert über die Assoziation <code>+blockIfStateActiveCp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>ModeDeclaration</code>: Spezialisierung von <code>AtpStructureElement</code> und <code>Identifiable</code>. Besitzt das Attribut <code>+ value: PositiveInteger [0..1]</code>. Dient der Referenzierung von Zuständen im AP-Kontext mittels Instanzreferenz (<code>«instanceRef»</code>) über die gerichtete Beziehung <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>FunctionGroupStateInFunctionGroupSetInstanceRef</code>: Spezialisierung von <code>AtpInstanceRef</code> (farblich als Instanzreferenz-Container hervorgehoben). Eingebunden per Komposition (ausgefüllte Raute) über die Rolle <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bewertet die Filterlogik eines <code>SecurityEventStateFilter</code> beim Eintreffen eines Sicherheitsereignisses den aktuellen Systemzustand: Befindet sich das System in einem Zustand, der über <code>blockIfStateActiveCp</code> (Classic Platform) oder über <code>blockIfStateActiveAp</code> (Adaptive Platform bzw. Execution Management Function Groups) hinterlegt ist, wird das Event blockiert bzw. nicht weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-M2-Metamodell für Security Extracts. Konfiguratoren und Werkzeugketten müssen bei der Modellierung von <code>SecurityEventStateFilter</code> sicherstellen, dass je nach Zielplattform (CP oder AP) die korrekten Zustandsreferenzen modelliert werden: <code>BlockState</code> für CP-Zustände sowie <code>FunctionGroupStateInFunctionGroupSetInstanceRef</code> bzw. <code>ModeDeclaration</code> für AP-Funktionsgruppenzustände. Alle Rollen besitzen die Kardinalität <code>0..*</code> und sind somit optional sowie mehrfach instanziierbar.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e831ac7c0570e8cb", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im Kontext des AUTOSAR Security Extract Templates (<code>AUTOSAR_TPS_SecurityExtractTemplate</code>). Das Modell definiert die Struktur des <code>SecurityEventStateFilter</code>, mit dem das Filtern bzw. Blockieren von Security-Events in Abhängigkeit von aktuellen Systemzuständen sowohl für die Classic Platform (CP) als auch für die Adaptive Platform (AP) konfiguriert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>SecurityEventStateFilter</code>: Spezialisierung von <code>AbstractSecurityEventFilter</code>. Zentrale Filterklasse zur Zustandsfilterung von Security-Events.\n</li><li><code>BlockState</code>: Spezialisierung von <code>Identifiable</code>. Repräsentiert Blockierzustände für die Classic Platform. Referenziert über die Assoziation <code>+blockIfStateActiveCp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>ModeDeclaration</code>: Spezialisierung von <code>AtpStructureElement</code> und <code>Identifiable</code>. Besitzt das Attribut <code>+ value: PositiveInteger [0..1]</code>. Dient der Referenzierung von Zuständen im AP-Kontext mittels Instanzreferenz (<code>«instanceRef»</code>) über die gerichtete Beziehung <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>FunctionGroupStateInFunctionGroupSetInstanceRef</code>: Spezialisierung von <code>AtpInstanceRef</code> (farblich als Instanzreferenz-Container hervorgehoben). Eingebunden per Komposition (ausgefüllte Raute) über die Rolle <code>+blockIfStateActiveAp</code> mit der Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bewertet die Filterlogik eines <code>SecurityEventStateFilter</code> beim Eintreffen eines Sicherheitsereignisses den aktuellen Systemzustand: Befindet sich das System in einem Zustand, der über <code>blockIfStateActiveCp</code> (Classic Platform) oder über <code>blockIfStateActiveAp</code> (Adaptive Platform bzw. Execution Management Function Groups) hinterlegt ist, wird das Event blockiert bzw. nicht weitergeleitet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-M2-Metamodell für Security Extracts. Konfiguratoren und Werkzeugketten müssen bei der Modellierung von <code>SecurityEventStateFilter</code> sicherstellen, dass je nach Zielplattform (CP oder AP) die korrekten Zustandsreferenzen modelliert werden: <code>BlockState</code> für CP-Zustände sowie <code>FunctionGroupStateInFunctionGroupSetInstanceRef</code> bzw. <code>ModeDeclaration</code> für AP-Funktionsgruppenzustände. Alle Rollen besitzen die Kardinalität <code>0..*</code> und sind somit optional sowie mehrfach instanziierbar.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a4350d1e948d085d", "to": "FIG-a601aa03f5394eaa", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a601aa03f5394eaa", "to": "FIG-e831ac7c0570e8cb", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
